// ── Scaled Dot-Product Attention — worked numeric example ──────
//
// We have 3 tokens with d_k=2 for illustration.
// In a real model, d_k = d_model / num_heads (e.g. 4096/32 = 128).

function softmax(arr) {
  const max = Math.max(...arr);           // numeric stability: subtract max
  const exps = arr.map(x => Math.exp(x - max));
  const sum = exps.reduce((a, b) => a + b, 0);
  return exps.map(e => e / sum);
}

function dot(a, b) {
  return a.reduce((s, v, i) => s + v * b[i], 0);
}

// Q, K, V for 3 tokens (each a 2-dim vector for illustration)
const Q = [[1, 0], [0, 1], [1, 1]];   // queries
const K = [[1, 0], [0, 1], [0, 0]];   // keys
const V = [[10, 0], [0, 10], [5, 5]]; // values
const dk = 2;  // query/key dimension

// Compute attention for token 0:
// -- score[j] = Q[0] · K[j] / sqrt(dk)
const scores0 = K.map(k => dot(Q[0], k) / Math.sqrt(dk));
console.log('Raw scores for token 0:', scores0.map(s => s.toFixed(3)));
// Q[0]=[1,0] · K[0]=[1,0] = 1  →  1/sqrt(2) ≈ 0.707
// Q[0]=[1,0] · K[1]=[0,1] = 0  →  0/sqrt(2) = 0.000
// Q[0]=[1,0] · K[2]=[0,0] = 0  →  0/sqrt(2) = 0.000

const weights0 = softmax(scores0);
console.log('Attention weights:', weights0.map(w => w.toFixed(3)));
// [ 0.576, 0.212, 0.212 ]  — token 0 attends mostly to itself

// Weighted sum of Value vectors
const out0 = V[0].map((_, i) =>
  weights0.reduce((s, w, j) => s + w * V[j][i], 0)
);
console.log('Attention output for token 0:', out0.map(v => v.toFixed(2)));
// ≈ [6.48, 2.12]  (mostly value[0]=[10,0] plus small contributions from others)

// ── Why the sqrt(dk) scaling matters ──────────────────────────
// Without scaling, large dk causes huge dot products → softmax saturates
// to near-one-hot → gradients vanish for all non-max positions
const dkLarge = 64;
const bigScore = [8.0, 7.9, 0.1];                    // plausible for large dk
const unscaled = softmax(bigScore);                   // [0.731, 0.269, 0.000]
const scaled   = softmax(bigScore.map(s => s / Math.sqrt(dkLarge)));
console.log('Unscaled softmax:', unscaled.map(s => s.toFixed(3)));
console.log('Scaled softmax:  ', scaled.map(s => s.toFixed(3)));
// Scaling makes the distribution less peaked → healthier gradients

// ── Token counting and context window ─────────────────────────
function estimateTokens(text) {
  const words = text.trim().split(/\s+/).length;
  return {
    byWords: Math.ceil(words / 0.75),   // 1 token ≈ 0.75 English words
    byChars: Math.ceil(text.length / 4) // 1 token ≈ 4 chars
  };
}

const paragraph = 'The quick brown fox jumps over the lazy dog. '
  + 'This sentence is used to illustrate token counting.';
console.log('Estimated tokens:', estimateTokens(paragraph));
// byWords: 24, byChars: 27  (actual GPT-4o: ~26 tokens)

// ── Temperature sampling simulation ───────────────────────────
//
// Illustrates how temperature changes the probability distribution
// over the vocabulary before sampling.

function softmax(logits) {
  const max = Math.max(...logits);
  const exps = logits.map(x => Math.exp(x - max));
  const sum = exps.reduce((a, b) => a + b, 0);
  return exps.map(e => e / sum);
}

// Toy vocabulary: 5 possible next tokens with raw logits
const tokens   = ['Paris', 'London', 'Berlin', 'Rome', 'Madrid'];
const logits   = [4.2, 2.8, 1.5, 0.9, 0.3];  // model's raw scores

function applyTemperature(logits, temperature) {
  if (temperature === 0) {
    // Greedy: one-hot at argmax
    const maxIdx = logits.indexOf(Math.max(...logits));
    return logits.map((_, i) => i === maxIdx ? 1.0 : 0.0);
  }
  return softmax(logits.map(l => l / temperature));
}

const temperatures = [0.0, 0.5, 1.0, 1.5];
for (const T of temperatures) {
  const probs = applyTemperature(logits, T);
  const label = T === 0 ? 'greedy' : `T=${T}`;
  console.log(`\n[${label}]`);
  tokens.forEach((t, i) => console.log(`  ${t.padEnd(8)} ${(probs[i]*100).toFixed(1)}%`));
}
// [greedy]   Paris: 100%, all others: 0%
// [T=0.5]    Paris:  96%, London: 3%, Berlin: 1%
// [T=1.0]    Paris:  66%, London: 22%, Berlin: 8%  (softmax of raw logits)
// [T=1.5]    Paris:  44%, London: 28%, Berlin: 16% (flatter)

// ── Top-p (nucleus) sampling ───────────────────────────────────
function topPSample(probs, p) {
  // Sort tokens by probability descending, take smallest set summing to >= p
  const sorted = probs
    .map((prob, i) => ({ i, prob }))
    .sort((a, b) => b.prob - a.prob);

  let cumulative = 0;
  const nucleus = [];
  for (const item of sorted) {
    nucleus.push(item);
    cumulative += item.prob;
    if (cumulative >= p) break;
  }

  // Renormalise within nucleus and sample (here we just show the nucleus)
  return nucleus.map(({ i }) => tokens[i]);
}

const probs1 = applyTemperature(logits, 1.0);
console.log('\nTop-p=0.9 nucleus:', topPSample(probs1, 0.9));
// ['Paris', 'London', 'Berlin']  — these 3 together exceed 90% probability

// ── Context window check ───────────────────────────────────────
const MODEL_LIMITS = {
  'gpt-4o':            128_000,
  'claude-3-5-sonnet': 200_000,
  'gemini-1-5-pro':  1_000_000,
};

function checkFitsInContext(text, model) {
  const estimatedTokens = Math.ceil(text.length / 4);
  const limit = MODEL_LIMITS[model];
  return {
    estimatedTokens,
    limit,
    fits: estimatedTokens <= limit,
    percentUsed: ((estimatedTokens / limit) * 100).toFixed(1) + '%'
  };
}

const longDoc = 'x'.repeat(400_000); // 400k chars ≈ 100k tokens
console.log(checkFitsInContext(longDoc, 'gpt-4o'));
// { estimatedTokens: 100000, limit: 128000, fits: true, percentUsed: '78.1%' }

// ── LLM Parameter count estimation ────────────────────────────
// Simplified — ignores bias terms and layer norm params (minor)

function estimateParams(config) {
  const {
    vocabSize, dModel, numLayers, ffnMultiplier = 4
  } = config;

  // Embedding matrix
  const embeddingParams = vocabSize * dModel;

  // Per-block: 4 attention matrices (Wq, Wk, Wv, Wo) + 2 FFN matrices
  // Attention: 4 * (d_model * d_model) — simplified (ignores multi-head split)
  const attnParams  = 4 * dModel * dModel;
  // FFN: W1 (d_model→4*d_model) + W2 (4*d_model→d_model)
  const ffnParams   = 2 * dModel * (ffnMultiplier * dModel);
  const perBlock    = attnParams + ffnParams;

  // Output head (unembedding — often weight-tied with embedding)
  const outputParams = vocabSize * dModel; // 0 if tied

  const total = embeddingParams + numLayers * perBlock + outputParams;
  return {
    embeddingParams: (embeddingParams / 1e6).toFixed(0) + 'M',
    perBlockParams:  (perBlock / 1e6).toFixed(1) + 'M',
    totalParams:     (total / 1e9).toFixed(2) + 'B'
  };
}

// LLaMA 3 8B approximation
console.log('LLaMA 3 8B:', estimateParams({
  vocabSize: 128_000,
  dModel: 4096,
  numLayers: 32
}));
// embeddingParams: 524M, perBlock: 201.3M, totalParams: ~8B

// GPT-2 (original, 117M)
console.log('GPT-2 small:', estimateParams({
  vocabSize: 50_257,
  dModel: 768,
  numLayers: 12
}));
// totalParams: ~0.12B (117M)

// Chinchilla optimal tokens for a given parameter count
function chinchillaTokens(numParams) {
  // Optimal: ~20 tokens per parameter (Hoffmann et al. 2022)
  const tokens = numParams * 20;
  return {
    optimalTokens: (tokens / 1e9).toFixed(1) + 'B tokens',
    note: 'Training beyond this is "overtraining" but improves inference efficiency'
  };
}

console.log('Chinchilla optimal for 7B model:', chinchillaTokens(7e9));
// optimalTokens: '140.0B tokens'  (LLaMA 3 uses 15T — intentionally overtrained)
